// *** GOOD: Constructor injection with Lombok @RequiredArgsConstructor ***
package com.bank.loan.service;

import com.bank.loan.audit.AuditService;
import com.bank.loan.dto.*;
import com.bank.loan.model.LoanApplication;
import com.bank.loan.repository.LoanApplicationRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.UUID;

@Service
@RequiredArgsConstructor  // Generates constructor for ALL final fields
@Slf4j
public class LoanApprovalService {

    // ─── ALL dependencies are final → immutable, explicit, testable ───
    private final CreditScoreService creditScoreService;        // required
    private final RiskAssessmentService riskAssessmentService;  // required
    private final LoanApplicationRepository loanRepo;           // required
    private final AuditService auditService;                    // required

    // Lombok generates THIS constructor automatically:
    // LoanApprovalService(CreditScoreService css, RiskAssessmentService ras,
    //                     LoanApplicationRepository lr, AuditService as) {
    //     this.creditScoreService = css;
    //     this.riskAssessmentService = ras;
    //     this.loanRepo = lr;
    //     this.auditService = as;
    // }
    // Spring detects the single constructor and injects — NO @Autowired needed.

    @Value("${loan.min-credit-score:650}")
    private int minCreditScore;

    @Transactional
    public LoanDecision processApplication(LoanRequest request) {
        String appId = "LOAN-" + UUID.randomUUID().toString().substring(0, 8).toUpperCase();
        log.info("Processing loan application {} for customer {}", appId, request.customerId());

        // Step 1: Check credit score
        int creditScore = creditScoreService.getCreditScore(request.customerId());

        // Step 2: Create loan application entity
        LoanApplication application = new LoanApplication(
            appId, request.customerId(), request.amount(), request.tenureMonths());

        // Step 3: Decision
        if (creditScore < minCreditScore) {
            String reason = "Credit score " + creditScore + " below minimum " + minCreditScore;
            application.reject(reason);
            loanRepo.save(application);
            auditService.logDecision(appId, "REJECTED", reason);
            return new LoanDecision(appId, "REJECTED", null, reason);
        }

        // Step 4: Calculate rate and approve
        BigDecimal rate = riskAssessmentService.calculateInterestRate(creditScore);
        application.approve(rate);
        loanRepo.save(application);
        auditService.logDecision(appId, "APPROVED", "Rate: " + rate + "%");

        return new LoanDecision(appId, "APPROVED", rate, "Approved at " + rate + "% interest");
    }
}
