// *** FAST unit test — NO Spring context, NO database. Just new + mocks. ***
package com.bank.loan.service;

import com.bank.loan.audit.AuditService;
import com.bank.loan.dto.*;
import com.bank.loan.model.LoanApplication;
import com.bank.loan.repository.LoanApplicationRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.*;
import org.mockito.junit.jupiter.MockitoExtension;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class LoanApprovalServiceTest {

    @Mock CreditScoreService creditScoreService;
    @Mock RiskAssessmentService riskAssessmentService;
    @Mock LoanApplicationRepository loanRepo;
    @Mock AuditService auditService;

    @InjectMocks LoanApprovalService loanApprovalService;

    @Test
    void shouldApproveLoanForGoodCreditScore() {
        // Given
        when(creditScoreService.getCreditScore("CUST001")).thenReturn(750);
        when(riskAssessmentService.calculateInterestRate(750)).thenReturn(new BigDecimal("7.50"));
        when(loanRepo.save(any(LoanApplication.class))).thenAnswer(i -> i.getArgument(0));

        // When
        LoanDecision decision = loanApprovalService.processApplication(
            new LoanRequest("CUST001", new BigDecimal("500000"), 60));

        // Then
        assertThat(decision.status()).isEqualTo("APPROVED");
        assertThat(decision.interestRate()).isEqualByComparingTo("7.50");
        verify(auditService).logDecision(anyString(), eq("APPROVED"), contains("7.50"));
        verify(loanRepo).save(any(LoanApplication.class));
    }

    @Test
    void shouldRejectLoanForLowCreditScore() {
        when(creditScoreService.getCreditScore("CUST003")).thenReturn(520);

        LoanDecision decision = loanApprovalService.processApplication(
            new LoanRequest("CUST003", new BigDecimal("500000"), 60));

        assertThat(decision.status()).isEqualTo("REJECTED");
        assertThat(decision.reason()).contains("520").contains("below minimum");
        verify(riskAssessmentService, never()).calculateInterestRate(anyInt());
        verify(auditService).logDecision(anyString(), eq("REJECTED"), contains("520"));
    }
}
// Test runs in ~50ms. No Spring. No DB. Just constructor injection + mocks.
